questions.q:
What does this print?
for i in range(3):
    print(i)

challenge.solution:
results = []
for n in range(1, 16):
    if n % 15 == 0:
        results.append("FizzBuzz")
    elif n % 3 == 0:
        results.append("Fizz")
    elif n % 5 == 0:
        results.append("Buzz")
    else:
        results.append(str(n))
print(" ".join(results))

def average(numbers):
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)

print(average([4, 8, 6]))
print(average([]))

sentence = "the cat and the hat"
counts = {}
for word in sentence.split():
    counts[word] = counts.get(word, 0) + 1
print(counts)

def to_number(text):
    try:
        return int(text)
    except ValueError:
        return None

print(to_number("42"))
print(to_number("forty"))
